    "cases": [
      {
        "input": [
          {
            "parameter": "r",
            "value": "new CNAMERecord(Name.fromString(\"alias.example.\"), DClass.IN, 300, Name.fromString(\"target.example.\"))"
          }
        ],
        "expected": "Message whose QUESTION section contains the supplied CNAMERecord and whose header has Opcode QUERY and RD flag set",
        "description": "Verifies that newQuery correctly creates a query for a CNAME record type."
      },
      {
        "input": [
          {
            "parameter": "r",
            "value": "new AAAARecord(Name.fromString(\"ipv6.example.\"), DClass.IN, 400, InetAddress.getByName(\"2001:db8::1\"))"
          }
        ],
        "expected": "Message whose QUESTION section contains the supplied AAAARecord and whose header has Opcode QUERY and RD flag set",
        "description": "Ensures newQuery works for an AAAA (IPv6) record."
      },
      {
        "input": [
          {
            "parameter": "r",
            "value": "new SRVRecord(Name.fromString(\"_sip._tcp.example.\"), DClass.IN, 500, 10, 20, 5060, Name.fromString(\"sipserver.example.\"))"
          }
        ],
        "expected": "Message whose QUESTION section contains the supplied SRVRecord and whose header has Opcode QUERY and RD flag set",
        "description": "Checks handling of a service (SRV) record."
      }
    ]
  },
  "newQuery - non‑IN class": {
    "cases": [
      {
        "input": [
          {
            "parameter": "r",
            "value": "new TXTRecord(Name.fromString(\"class.ch.\"), DClass.CH, 300, \"class test\")"
          }
        ],
        "expected": "Message with QUESTION containing the TXTRecord (class CH) and header Opcode QUERY, RD flag set",
        "description": "Validates that newQuery does not enforce DClass.IN and can create queries for other DNS classes."
      }
    ]
  },
  "newQuery - zero TTL": {
    "cases": [
      {
        "input": [
          {
            "parameter": "r",
            "value": "new ARecord(Name.fromString(\"zero.ttl.example.\"), DClass.IN, 0, InetAddress.getByName(\"192.0.2.1\"))"
          }
        ],
        "expected": "Message whose QUESTION section contains the ARecord with TTL 0; header remains Opcode QUERY and RD flag set",
        "description": "Ensures that a record with a TTL of zero does not cause any special handling in newQuery."
      }
    ]
  },
